import sys, numpy as np
sys.path.insert(0,'source/src')
import porespy as ps
cases=[]
for shape in [(7,8),(8,7),(5,6,7),(6,7,5),(4,4,4),(1,8),(8,1)]:
 rng=np.random.default_rng(sum(shape)); im=rng.random(shape)<.3; cases.append((shape,im))
for shape,im in cases:
 print('\\n',shape)
 for bins in [3, np.array([0,1,2,3],dtype=float)]:
  try:
   r=ps.metrics.two_point_correlation(im,bins=bins,voxel_size=2)
   print('bins',bins,'shapes',r.distance.shape,'finite',np.all(np.isfinite(r.probability)), 'd',r.distance)
  except Exception as e: print('ERR',type(e).__name__,e)
PY"

